1	//! Permission layer: gate tool calls via deny rules → permission mode →
2	//! `canUseTool` policy. See the *Permissions, Guardrails & Hooks* concept page.
3	
4	use async_trait::async_trait;
5	
6	use crate::RunContext;
7	
8	/// How permission mode governs tool calls.
9	///
10	/// `Bypass` propagates to subagents and **cannot be overridden** — a typed
11	/// enum, not a string. The non-override property is enforced by
12	/// [`RunContext::with_permission_mode`], which refuses to downgrade `Bypass`.
13	#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
14	#[non_exhaustive]
15	pub enum PermissionMode {
16	    /// Defer to the policy (ask for unfamiliar tools); permissive when no policy.
17	    #[default]
18	    Default,
19	    /// Auto-approve tools with a [`crate::ToolEffect::Write`] effect; all other
20	    /// tools still reach the policy.
21	    AcceptEdits,
22	    /// Read-only: deny any tool whose [`crate::ToolEffect`] is not `ReadOnly`.
23	    Plan,
24	    /// Dangerous: allow all (deny rules still apply). Propagates; sticky.
25	    Bypass,
26	}
27	
28	/// The outcome of a [`PermissionPolicy::check`] (or the resolved decision).
29	#[derive(Debug, Clone)]
30	#[non_exhaustive]
31	pub enum PermissionDecision {
32	    /// Run the call unchanged.
33	    Allow,
34	    /// Block the call; the reason is surfaced to the model as a tool result.
35	    Deny {
36	        /// Human-readable denial reason.
37	        reason: String,
38	    },
39	    /// Ask a human (resolved via [`ApprovalHandler`]; default Deny).
40	    AskUser {
41	        /// Prompt shown to the approver.
42	        prompt: String,
43	    },
44	    /// Replace the call's arguments before execution (sanitize).
45	    Replace {
46	        /// Replacement JSON arguments.
47	        args: serde_json::Value,
48	    },
49	}
50	
51	/// Authorizes a tool call. The decision pipeline runs
52	/// `deny rules › mode › this policy` (see `control.rs`).
53	#[async_trait]
54	pub trait PermissionPolicy<Ctx>: Send + Sync
55	where
56	    Ctx: Send + Sync + 'static,
57	{
58	    /// Decide whether `tool` may run with `args`.
59	    async fn check(
60	        &self,
61	        ctx: &RunContext<Ctx>,
62	        tool: &str,
63	        args: &serde_json::Value,
64	    ) -> PermissionDecision;
65	}
66	
67	/// How a [`DenyRule`] matches a call.
68	#[derive(Debug, Clone, PartialEq, Eq)]
69	enum Matcher {
70	    /// Exact tool name.
71	    Tool(String),
72	    /// Any Bash sub-command whose resolved program equals this. Tool-scoped to
73	    /// the `Bash` tool.
74	    BashProgram(String),
75	}
76	
77	/// A first-class deny rule, evaluated **before** mode — so it overrides even
78	/// [`PermissionMode::Bypass`].
79	#[derive(Debug, Clone, PartialEq, Eq)]
80	pub struct DenyRule {
81	    matcher: Matcher,
82	}
83	
84	impl DenyRule {
85	    /// Deny a tool by its exact name.
86	    pub fn tool(name: impl Into<String>) -> Self {
87	        Self {
88	            matcher: Matcher::Tool(name.into()),
89	        }
90	    }
91	
92	    /// Deny a Bash call whose compound command contains a sub-command whose
93	    /// resolved program equals `program` (operator-, wrapper-, and
94	    /// `bash -c`-aware). Only matches the `Bash` tool.
95	    pub fn bash_command(program: impl Into<String>) -> Self {
96	        Self {
97	            matcher: Matcher::BashProgram(program.into()),
98	        }
99	    }
100	
101	    /// `true` if this rule denies `tool` invoked with `args`.
102	    pub fn matches(&self, tool: &str, args: &serde_json::Value) -> bool {
103	        match &self.matcher {
104	            Matcher::Tool(name) => name == tool,
105	            Matcher::BashProgram(program) => {
106	                if tool != "Bash" {
107	                    return false;
108	                }
109	                let Some(command) = args.get("command").and_then(|v| v.as_str()) else {
110	                    return false;
111	                };
112	                crate::command_match::resolve_all(command)
113	                    .iter()
114	                    .any(|c| &c.program == program)
115	            }
116	        }
117	    }
118	}
119	
120	/// Resolves a [`PermissionDecision::AskUser`] when the driver cannot decide
121	/// inline. Non-generic — it needs no `Ctx`.
122	#[async_trait]
123	pub trait ApprovalHandler: Send + Sync {
124	    /// Decide an `AskUser` prompt. Returns a narrowed [`ApprovalOutcome`]
125	    /// (cannot recursively ask).
126	    async fn decide(&self, tool: &str, prompt: &str, args: &serde_json::Value) -> ApprovalOutcome;
127	}
128	
129	/// The narrowed decision an [`ApprovalHandler`] may return.
130	#[derive(Debug, Clone)]
131	#[non_exhaustive]
132	pub enum ApprovalOutcome {
133	    /// Allow the call.
134	    Allow,
135	    /// Deny the call with a reason.
136	    Deny {
137	        /// Human-readable denial reason.
138	        reason: String,
139	    },
140	}
141	
142	/// The action a tripped [`GuardRule`] takes. Evaluated **before** mode, so it
143	/// overrides even [`PermissionMode::Bypass`].
144	#[derive(Debug, Clone, PartialEq, Eq)]
145	#[non_exhaustive]
146	pub enum GuardAction {
147	    /// Hard-deny with a reason.
148	    Deny {
149	        /// Human-readable denial reason.
150	        reason: String,
151	    },
152	    /// Ask a human via the [`ApprovalHandler`] (default Deny when none).
153	    Ask {
154	        /// Prompt shown to the approver.
155	        prompt: String,
156	    },
157	}
158	
159	#[derive(Debug, Clone, PartialEq, Eq)]
160	enum GuardMatcher {
161	    /// `rm` with recursive+force flags targeting `/` or `~` (literal).
162	    RmRecursiveRootOrHome,
163	    /// A write whose target resolves under a protected prefix (Bash redirects,
164	    /// `tee`/`dd`, or the Write/Edit `path` arg). Honors the device-node allowlist.
165	    ProtectedPathWrite,
166	}
167	
168	/// A pre-mode safety rule. Like [`DenyRule`] it runs before permission mode and
169	/// beats `Bypass`, but it may **ask** a human instead of hard-denying.
170	#[derive(Debug, Clone, PartialEq, Eq)]
171	pub struct GuardRule {
172	    matcher: GuardMatcher,
173	    action: GuardAction,
174	}
175	
176	/// Protected path prefixes. A write resolving under any of these trips
177	/// [`GuardMatcher::ProtectedPathWrite`].
178	const PROTECTED_PREFIXES: &[&str] = &["/etc", "/usr", "/bin", "/sbin", "/sys", "/boot", "/dev"];
179	
180	/// Device nodes that are safe write targets despite the `/dev` prefix. Checked
181	/// before the protected-prefix rule so `cmd > /dev/null` is never denied.
182	const DEVICE_ALLOWLIST: &[&str] = &[
183	    "/dev/null",
184	    "/dev/zero",
185	    "/dev/full",
186	    "/dev/stdout",
187	    "/dev/stderr",
188	    "/dev/tty",
189	    "/dev/random",
190	    "/dev/urandom",
191	];
192	
193	impl GuardRule {
194	    /// The action this rule takes when it matches.
195	    pub fn action(&self) -> &GuardAction {
196	        &self.action
197	    }
198	
199	    /// `true` if this guard trips for `tool` invoked with `args`.
200	    pub fn matches(&self, tool: &str, args: &serde_json::Value) -> bool {
201	        match &self.matcher {
202	            GuardMatcher::RmRecursiveRootOrHome => {
203	                let Some(cmd) = bash_command_str(tool, args) else {
204	                    return false;
205	                };
206	                crate::command_match::resolve_all(cmd)
207	                    .iter()
208	                    .any(is_rm_rf_root_or_home)
209	            }
210	            GuardMatcher::ProtectedPathWrite => protected_path_write(tool, args),
211	        }
212	    }
213	
214	    /// The always-on destructive guard set: `rm -rf /`, `rm -rf ~`, and
215	    /// protected-path writes. All default to [`GuardAction::Ask`].
216	    pub fn destructive_defaults() -> Vec<GuardRule> {
217	        vec![
218	            GuardRule {
219	                matcher: GuardMatcher::RmRecursiveRootOrHome,
220	                action: GuardAction::Ask {
221	                    prompt: "destructive command: recursive force-remove of / or ~".to_owned(),
222	                },
223	            },
224	            GuardRule {
225	                matcher: GuardMatcher::ProtectedPathWrite,
226	                action: GuardAction::Ask {
227	                    prompt: "write to a protected system path".to_owned(),
228	                },
229	            },
230	        ]
231	    }
232	}
233	
234	fn bash_command_str<'a>(tool: &str, args: &'a serde_json::Value) -> Option<&'a str> {
235	    if tool != "Bash" {
236	        return None;
237	    }
238	    args.get("command").and_then(|v| v.as_str())
239	}
240	
241	fn is_rm_rf_root_or_home(cmd: &crate::command_match::ResolvedCommand) -> bool {
242	    if cmd.program != "rm" {
243	        return false;
244	    }
245	    let mut recursive = false;
246	    let mut force = false;
247	    let mut targets: Vec<&str> = Vec::new();
248	    for a in &cmd.args {
249	        if a.starts_with("--") {
250	            match a.as_str() {
251	                "--recursive" => recursive = true,
252	                "--force" => force = true,
253	                _ => {}
254	            }
255	        } else if let Some(flags) = a.strip_prefix('-') {
256	            if flags.contains('r') || flags.contains('R') {
257	                recursive = true;
258	            }
259	            if flags.contains('f') {
260	                force = true;
261	            }
262	        } else {
263	            targets.push(a);
264	        }
265	    }
266	    recursive && force && targets.iter().any(|t| is_root_or_home(t))
267	}
268	
269	fn is_root_or_home(target: &str) -> bool {
270	    matches!(target, "/" | "/*" | "~" | "~/" | "${HOME}" | "$HOME")
271	}
272	
273	fn protected_path_write(tool: &str, args: &serde_json::Value) -> bool {
274	    if matches!(tool, "Write" | "Edit") {
275	        if let Some(p) = args.get("path").and_then(|v| v.as_str()) {
276	            return is_protected_path(p);
277	        }
278	    }
279	    if let Some(cmd) = bash_command_str(tool, args) {
280	        for c in crate::command_match::resolve_all(cmd) {
281	            for r in &c.redirects {
282	                use crate::command_match::RedirectOp;
283	                if matches!(r.op, RedirectOp::Out | RedirectOp::Append)
284	                    && is_protected_path(&r.target)
285	                {
286	                    return true;
287	                }
288	            }
289	            if c.program == "tee" && c.args.iter().any(|a| is_protected_path(a)) {
290	                return true;
291	            }
292	            if c.program == "dd" {
293	                if let Some(of) = c.args.iter().find_map(|a| a.strip_prefix("of=")) {
294	                    if is_protected_path(of) {
295	                        return true;
296	                    }
297	                }
298	            }
299	        }
300	    }
301	    false
302	}
303	
304	fn is_protected_path(path: &str) -> bool {
305	    if DEVICE_ALLOWLIST.contains(&path) {
306	        return false;
307	    }
308	    if path == "/" {
309	        return true;
310	    }
311	    PROTECTED_PREFIXES
312	        .iter()
313	        .any(|p| path == *p || path.starts_with(&format!("{p}/")))
314	}
