194	#[cfg(test)]
195	mod guardrail_tests {
196	    use super::*;
197	    use crate::{
198	        CancellationToken, GuardrailError, GuardrailInput, GuardrailKind, GuardrailVerdict,
199	        HookRegistry, MemorySession, RunContext, Session, TracerHandle,
200	    };
201	    use async_trait::async_trait;
202	
203	    struct TripOnInput;
204	    #[async_trait]
205	    impl Guardrail<()> for TripOnInput {
206	        async fn check(
207	            &self,
208	            _: &RunContext<()>,
