fn build_globset(pattern: &str) -> GlobSet {
    let globs: Vec<String> = if pattern.contains('/') {
        vec![pattern.to_owned()]
    } else {
        vec![pattern.to_owned(), format!("**/{pattern}")]
    };
    let mut builder = GlobSetBuilder::new();
